import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"履","description":"焦氏易林注 - 履","frontmatter":{"title":"履","description":"焦氏易林注 - 履"},"headers":[],"relativePath":"classics/jiaoyilin/010.md","filePath":"classics/jiaoyilin/010.md"}'),l={name:"classics/jiaoyilin/010.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="履" tabindex="-1">履 <a class="header-anchor" href="#履" aria-label="Permalink to “履”">​</a></h1><h3 id="履-1" tabindex="-1">履 <a class="header-anchor" href="#履-1" aria-label="Permalink to “履”">​</a></h3><h3 id="履之乾" tabindex="-1">履之乾 <a class="header-anchor" href="#履之乾" aria-label="Permalink to “履之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>東向蕃坦，相與笑言。子般執鞭，圉人作患。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用《履》象。巽為蕃垣，蕃，垣牆也。蕃與藩通。《詩大雅》：&quot;四國於藩是也&quot;，離東故曰東向。初至五兩兌口相對，故曰相與笑言。伏震為子、為般，般，反也。伏艮為執，巽為鞭，故曰執鞭。艮為圉，坎為患。《左傳莊三十二年》：&quot;雩女公子觀之，圉人犖自牆外與之戲，子般鞭之，後犖弒閔&quot;，林全用其事。○圉患，從宋元本，汲古等本皆訛作樂，人作歡。○離東證。</p><h3 id="履之坤" tabindex="-1">履之坤 <a class="header-anchor" href="#履之坤" aria-label="Permalink to “履之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>循河榜舟，旁淮東遊。漁父舉網，先得大暋。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>坤為河、為淮，履伏震為舟、為東，故曰東遊。坤為聚、為漁，乾為父，故曰漁父。離為網，坤為暎巽亦為暎兼用遇卦。○榜舟，從汲古，宋作樀，元作摘，皆訛。</p><h3 id="履之屯" tabindex="-1">履之屯 <a class="header-anchor" href="#履之屯" aria-label="Permalink to “履之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>轅折輪破，馬倚僕臥。後旅先宿，右足跌踒。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>震為轅，坎為輪、為折、為破，震馬艮僕，艮止，故馬倚僕臥。震為後、為行旅，坎為宿，震為足，遇險，故跌踒。○先，從宋元本，汲古作失。</p><h3 id="履之蒙" tabindex="-1">履之蒙 <a class="header-anchor" href="#履之蒙" aria-label="Permalink to “履之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>兩人相絆，相與悖戾。心乖不同，訟爭忷忷。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>震為人，正反震，故曰兩人。伏巽為繩，正反巽故相絆。坎為悖戾，兩人相背，故悖戾、故不同。坎為心，震為言，正反震故訟爭。○絆，從宋元本，汲古作伴。二三句從汲古，宋元作&quot;心不同爭，訟忷忷然&quot;，非。</p><h3 id="履之需" tabindex="-1">履之需 <a class="header-anchor" href="#履之需" aria-label="Permalink to “履之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>北辰紫宮，衣冠立中。含和建德，常受天福。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《觀》。○立，汲古作在。</p><h3 id="履之訟" tabindex="-1">履之訟 <a class="header-anchor" href="#履之訟" aria-label="Permalink to “履之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>遊居石門，祿安身全。受福西鄰，歸飲玉泉。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《既濟》。惟此以巽為石，乾為門。○巽為石、坎為西證，可解《易》。○第二句宋元本作&quot;祿身安全&quot;，汲古作&quot;祿祉安全&quot;，茲依《需》之《既濟》校。</p><h3 id="履之師" tabindex="-1">履之師 <a class="header-anchor" href="#履之師" aria-label="Permalink to “履之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>羊腸九縈，相推稍前。止須王孫，乃能上天。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>坤為腸，震為羊，數九，故曰九縈。震為王，伏乾為天，詳《蠱》之《剝》。</p><h3 id="履之比" tabindex="-1">履之比 <a class="header-anchor" href="#履之比" aria-label="Permalink to “履之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>爭訟相倍，和氣不處。陰陽俱否，谷風毋子。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>坎上下兩兌口相倍，倍，反也。坎為和，相倍故不和。谷風，《邶詩》篇名，毛謂為夫所棄，茲謂無子，是齊詩義也。坤為風。</p><h3 id="履之小畜" tabindex="-1">履之小畜 <a class="header-anchor" href="#履之小畜" aria-label="Permalink to “履之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>郭叔矩頤，為棘所拘。龍額重顙，禍不成殃，復歸其鄉。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>舊註皆雲故實未詳，蓋所據者古今無書，但以象論，似無訛字。卦通《豫》。艮為郭、為叔，兌為頤，坤方，故曰矩頤。坎為棘，艮拘震龍，艮為額、為顙，坤為重，故曰重顙。坤為禍，震解，故不成殃。艮為鄉，震為復、為歸。○矩，各本訛距。龍額，汲古作童顏，非，依宋本。</p><h3 id="履之履" tabindex="-1">履之履 <a class="header-anchor" href="#履之履" aria-label="Permalink to “履之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>十烏俱飛，羿射九雌。雄得獨全，雖驚不危。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>元刊《易林》舊註雲：&quot;堯時十日並出，羿射其九日，九烏皆死&quot;，離為烏，兌數十，故曰十烏。離為惡人，故曰羿。伏震為射，數九，故曰羿射九雌。坤為雌，坤伏乾出，故曰雄得獨全。伏震為驚，坎為險，坎伏故不危。○烏，從宋元本，他本多訛鳥。雄得獨全，雖驚不危，依汲古，宋本作&quot;雖得淂全&quot;，元本作&quot;雄雖得全&quot;，皆非。又雖驚宋元本作且驚，亦非。</p><h3 id="履之泰" tabindex="-1">履之泰 <a class="header-anchor" href="#履之泰" aria-label="Permalink to “履之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>蠆室蜂戶，螫我手足。不得進止，為吾害咎。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《明夷》。</p><h3 id="履之否" tabindex="-1">履之否 <a class="header-anchor" href="#履之否" aria-label="Permalink to “履之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>怒非其怨，因物有遷。貪妬腐鼠，而呼鴞鳶。自令失餌，倒被困患。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>伏震為怒，坤為物、為嫉妬。艮為鼠，巽敝，故曰腐鼠。艮為鴞鳶，震為呼，《莊子》：&quot;鴟得腐鼠，鵷雛過之，仰而視之曰：嚇&quot;，林似本此而變其意，言貪得腐鼠呼鴞鳶相助，豈知反為所奪而失餌也。○倒被困患，依丁本、局本，宋元二本皆作&quot;失反被困&quot;，汲古作&quot;到掖困患&quot;，自令失餌，依汲古增。</p><h3 id="履之同人" tabindex="-1">履之同人 <a class="header-anchor" href="#履之同人" aria-label="Permalink to “履之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>嬰孩求乳，母歸其子，黃麑悅喜。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>此用《履》伏象。震為嬰孩，艮為乳、為求，震為子、為歸，坤為母，坤舍震上，故曰母歸其子。震為鹿，麑，鹿子也，坤黃，故曰黃麑。震為喜。○宋元本末多&quot;自樂甘餌&quot;。</p><h3 id="履之大有" tabindex="-1">履之大有 <a class="header-anchor" href="#履之大有" aria-label="Permalink to “履之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>針縷徒勞，錦繡不成。鷹逐雉兔，爪折不得。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>此用《履》象。伏坎為針，巽為縷、為錦繡，兌毀，故曰徒勞、曰不成。伏艮為鷹，離為雉，震為兔、為足、為爪，坎蹇，故爪折不得。本象對象雜用。○徒勞，依汲古，宋元本作勝服。</p><h3 id="履之謙" tabindex="-1">履之謙 <a class="header-anchor" href="#履之謙" aria-label="Permalink to “履之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>雨潦集降，河渠不通。齊魯閉塞，破費市空。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>坤水坎水，故曰雨潦、曰河渠。坎為塞，故不通。伏巽為齊，兌為魯，坤閉，故曰齊魯閉塞。坎破，巽為市，坤虛，故市空。○渠、齊，依汲古，宋元作梁、作鄒。</p><h3 id="履之豫" tabindex="-1">履之豫 <a class="header-anchor" href="#履之豫" aria-label="Permalink to “履之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>封豕溝瀆，水潦空谷。客止舍宿，泥塗至腹，處無黍稷。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>坎為豕、為溝瀆，《天官書》&quot;奎為封豕為溝瀆，主江河之事&quot;，故曰水潦。坎為水。艮為谷，坤虛，故曰空谷。震為旅客，艮止艮舍。坎為宿、為泥塗，坤為腹，故曰至腹。震為黍稷，坤死故無。</p><h3 id="履之隨" tabindex="-1">履之隨 <a class="header-anchor" href="#履之隨" aria-label="Permalink to “履之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>三姦相擾，桀蹠為友。上下騷離，隔絕天道。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>震數三，巽為伏、為姦，震為擾，正反震，故曰相擾。兌剛，故曰桀，巽為盜，故曰蹠。艮上兌下，互大坎，故隔絕。艮為道。○友，依汲古，宋元本作交。</p><h3 id="履之蠱" tabindex="-1">履之蠱 <a class="header-anchor" href="#履之蠱" aria-label="Permalink to “履之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>齊景惑疑，為孺子牛。嫡庶不明，賊孽為患。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>巽為齊，互離日，故曰齊景，互坎，故疑惑。艮為孺子，離為牛，震為嫡子，兌為孽、為庶。坎為賊、為患、為孺子牛，事見《左傳哀六年》：&quot;鮑子曰：汝忘君之為孺子牛而折其齒乎&quot;，孺子名茶。</p><h3 id="履之臨" tabindex="-1">履之臨 <a class="header-anchor" href="#履之臨" aria-label="Permalink to “履之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>三羊俱亡，奔走南行。會暮失跡，不知所藏。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>兌為羊，震數三，故曰三羊俱亡。亡者，逃也。震為亡、為奔走、為南。坤為暮，震為跡，坤迷，故失跡。坤為藏，坤黑，故不知。○所，依宋元，汲古作其。</p><h3 id="履之觀" tabindex="-1">履之觀 <a class="header-anchor" href="#履之觀" aria-label="Permalink to “履之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>請伯行賈，岱山之野。夜厯險阻，不逢危殆，利如澆酒。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>通《大壯》。震為伯、為商賈，艮為山，震東，故曰岱山。坤為野、為夜，艮為險阻，巽為利酒，疑坤水象。○夜，依宋元本，汲古作犯。岱，宋元皆訛代，《韻補》雲：殆，音以。按：《易林》殆字十九葉以。</p><h3 id="履之噬嗑" tabindex="-1">履之噬嗑 <a class="header-anchor" href="#履之噬嗑" aria-label="Permalink to “履之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>桑之將落，隕其黃葉。失勢傾側，而無所立。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為桑，伏巽為落、為隕，震為黃，故曰隕其黃葉。坎陷為傾側、為失。○之，依宋元本，汲古作方，非。桑，依宋本，元本與汲古作葉，非。《詩衛風》：&quot;桑之落矣，其黃而隕。&quot;</p><h3 id="履之賁" tabindex="-1">履之賁 <a class="header-anchor" href="#履之賁" aria-label="Permalink to “履之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>上山求魚，入水捕狸。市非其歸，自令久留。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>震上，艮山，艮求，下離為魚，坎為水，艮為捕、為狸。狸在上而於下坎水捕之，魚在下而於上山求之，當然不得。伏巽為市。歸，聚也，言所市非地。艮止故久留。○狸，從宋本，汲古作兔。</p><h3 id="履之剝" tabindex="-1">履之剝 <a class="header-anchor" href="#履之剝" aria-label="Permalink to “履之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>名成德就，項領不試。景公耋老，尼父逝去。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮陽在上為名，坤為成，艮為項領。《詩小雅》：&quot;有鶯其領&quot;，《傳》：&quot;領，頸也&quot;。又&quot;四牧項領&quot;傳：&quot;項，大也&quot;，箋：但養大其領不肯為用，茲曰不試，與詩義同也，艮止，故不試。艮為火、為景，坤為老，伏乾為父，艮山，故曰尼父。坤死，故逝去。《論語》：&quot;景公曰：&quot;吾老矣，不能用也。&quot;孔子行。&quot;《左傳》：&quot;孔子卒，公誄之曰：哀哉尼父勿自律。&quot;</p><h3 id="履之復" tabindex="-1">履之復 <a class="header-anchor" href="#履之復" aria-label="Permalink to “履之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>天之奧隅，堯舜所居。可以存身，保我國家。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>伏乾為天，坤方大，故曰奧隅。震為帝，故曰堯舜。坤為聚、為居、為身、為國家，坤安為保。○第三句宋本作&quot;以存保身&quot;，依汲古。第四句宋元本作&quot;為我國家&quot;，汲古作&quot;保我邦國&quot;，茲保我依汲古，國家依宋元本。</p><h3 id="履之無妄" tabindex="-1">履之無妄 <a class="header-anchor" href="#履之無妄" aria-label="Permalink to “履之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>涉伯殉名，棄禮誅身。不得其道，成子奔燕。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>《左傳》：&quot;定九年，晉趙鞅圍衛，討衛之叛，曰：由涉佗、成何，遂殺涉佗，成何奔燕，君子曰：此之謂棄禮&quot;。震為伯，艮為名，坤為禮、為身，坤伏，故曰棄禮誅身。震為道，巽伏，故不得。艮為成，震為子、為奔、為燕。○宋元本作《頤》林。</p><h3 id="履之大畜" tabindex="-1">履之大畜 <a class="header-anchor" href="#履之大畜" aria-label="Permalink to “履之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>兩人俱爭，莫能有定。心乖不同，訟言起兇。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>震為人，三上正反震，故曰兩人、曰相爭、曰無定、曰心乖不同而訟也。伏坤為兇。</p><h3 id="履之頤" tabindex="-1">履之頤 <a class="header-anchor" href="#履之頤" aria-label="Permalink to “履之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>睢鳴淑女，賢聖配耦。宜家受福，吉慶長久。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>艮為鳥、為睢鳩。震淑坤女，伏乾為聖賢，乾坤為配偶，艮為家，震為福、為吉慶。艮為長久。○慶，依元本，汲古作善，宋本作《無妄》林。</p><h3 id="履之大過" tabindex="-1">履之大過 <a class="header-anchor" href="#履之大過" aria-label="Permalink to “履之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>逾江求橘，並得大慄。烹羊食炙，飲酒歌笑。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>伏坤為江河，震為逾，艮為橘、為求，乾為大、為木果，故為大慄，兌為羊、為飲食，大坎為酒，震為歌笑，正伏象雜用。○江，依宋元本，汲古作河。炙，依汲古，宋元作肉。飲，汲古作飯，依宋元本。</p><h3 id="履之坎" tabindex="-1">履之坎 <a class="header-anchor" href="#履之坎" aria-label="Permalink to “履之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>山險難行，磵中多石。車馳轊擊，重載折軸。擔負差躓，跌踒右足。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《謙》。○差，同蹉，依汲古，宋元本訛善。此等處汲古尚存真字，勝宋元本。</p><h3 id="履之離" tabindex="-1">履之離 <a class="header-anchor" href="#履之離" aria-label="Permalink to “履之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>允利孔福，神所子畜。般樂無苦，得其歡欲。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>互巽為利，伏震為孔、為福、為神、為子、為般樂、為歡。○允，從汲古，宋元本訛元。</p><h3 id="履之鹹" tabindex="-1">履之鹹 <a class="header-anchor" href="#履之鹹" aria-label="Permalink to “履之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>鳥鵲食榖，張口受哺。蒙被恩福，長大成就。柔順利貞，君臣合德。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>艮為鳥，兌為食，巽為榖，兌為口、為哺。乾為恩福，伏震為長。下艮為成，坤為柔順，巽為利，乾君艮臣，故曰合德。○德，依汲古，宋元本作好。</p><h3 id="履之恆" tabindex="-1">履之恆 <a class="header-anchor" href="#履之恆" aria-label="Permalink to “履之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>潼滃蔚薈，膚寸來會。津液下降，流潦滂沛。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《旅》，惟彼曰扶首來會，以艮為扶，互坎為首，巽為絲縷，故必曰扶首乃切。此則震為覆艮，艮為手。《公羊傳僖三十一年》何休註此句雲：側手為膚，按指為寸，艮覆象，側手，按指故必曰膚寸方切，或者不論何卦謂扶首是膚寸非者，殊不知林詞林字皆由象生也。</p><h3 id="履之遯" tabindex="-1">履之遯 <a class="header-anchor" href="#履之遯" aria-label="Permalink to “履之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>路多枳棘，步刺我足。不利旅客，為心作毒。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《賁》。</p><h3 id="履之大壯" tabindex="-1">履之大壯 <a class="header-anchor" href="#履之大壯" aria-label="Permalink to “履之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>虺蝮所聚，難以居處。毒螫痛甚，瘡不可愈。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>通《觀》。巽為蟲、為虺蝮。坤聚，艮居，坤害，故不可居。坤陰為毒螫，艮為節、為瘡，坤喪，故不可愈。○首句依宋元本，汲古作虺蛇求聚。</p><h3 id="履之晉" tabindex="-1">履之晉 <a class="header-anchor" href="#履之晉" aria-label="Permalink to “履之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>麟鳳相隨，察觀安危。東國聖人，后稷周公。君子攸同，利以居止，長無憂兇。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>離文坤文，故曰麟鳳、曰相隨。離為觀，艮安坎危，坤為國，離東，故曰東國。坎為聖，坤土為后稷，反震為周、為公，艮為君、為居止，坤為憂兇，離明在上，故不兇。○周公下宋元本多共和政令四字，汲古無。察觀，依汲古，宋元作觀察。東國，依汲古，宋元本作東鄰。</p><h3 id="履之明夷" tabindex="-1">履之明夷 <a class="header-anchor" href="#履之明夷" aria-label="Permalink to “履之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>桀亂不時，使民恨憂。六趾為笑，君危臣羞。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>離為惡人，坤亦為惡，故曰桀。離為亂，坤亦為亂，艮為時，艮覆，故曰不時。坤為民，坎為憂，震為趾，坎數六，故曰六趾。震為笑、為君，坤為臣、為羞，坎險故危。○桀，宋元作築，依汲古本，六，依汲古，宋本訛立。趾，依元本，宋本訛祉，汲古同。《莊子》：&quot;駢拇枝指&quot;註：枝指，六指也。駢拇，謂足拇指連第二指也。又雲二者或有餘於數或不足於數，其為憂一也，六趾或為六指，六指屢見他林。</p><h3 id="履之家人" tabindex="-1">履之家人 <a class="header-anchor" href="#履之家人" aria-label="Permalink to “履之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>黃帝所生，伏義之宇。兵刃不至，利以居止。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《萃》。 ○宇，宋元本作宅，失韻。</p><h3 id="履之睽" tabindex="-1">履之睽 <a class="header-anchor" href="#履之睽" aria-label="Permalink to “履之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>雀行求粒，暮歸屋宿。反其室舍，安寧如故。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《巽》。○屋宿反，依宋本，元本反作及。屋宿，汲古作喔嚅。如，依汲古，宋元本作無。又屋宿《比》之《巽》作孚乳，姑兩存之。</p><h3 id="履之蹇" tabindex="-1">履之蹇 <a class="header-anchor" href="#履之蹇" aria-label="Permalink to “履之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>太倉積榖，天下饒食。陰陽和調，年歲時熟。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>此用《履》伏象。艮為倉，震為榖，坤聚，故曰積榖、故曰饒食。坎為食也。坎為和，坤為年，歲艮為時。</p><h3 id="履之解" tabindex="-1">履之解 <a class="header-anchor" href="#履之解" aria-label="Permalink to “履之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>乾旄旌旗，執幟在郊。雖有寶珠，無路致之。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《隨》。○宋本作損林。</p><h3 id="履之損" tabindex="-1">履之損 <a class="header-anchor" href="#履之損" aria-label="Permalink to “履之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>履尾蹈顛，墜入寒淵。行不能前，足踒不便。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>震為履蹈，艮為尾、為顛，坤為淵、為寒，坤下，故墜。震為行，艮止，故不能前。兌折，故足踒。○尾，汲古作危，依宋元本。寒，依宋本，汲古作泉。行，依宋本，汲古作蹇，與下踒義復，故知宋本是，宋本作《解》林。</p><h3 id="履之益" tabindex="-1">履之益 <a class="header-anchor" href="#履之益" aria-label="Permalink to “履之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>銜命上車，合和兩家。蛾眉皓齒，二國不殆。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>巽為命，震口為銜、為上，坤為車，艮為家，正反艮相對，故曰和合兩家。巽為蛾，艮為眉，震為齒、為白，故曰蛾眉皓齒。坤為國，數二，震樂，故曰二國不殆。此似有故事，待考。○不殆，依汲古，宋元本訛率僵。</p><h3 id="履之夬" tabindex="-1">履之夬 <a class="header-anchor" href="#履之夬" aria-label="Permalink to “履之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>吉日車攻，田弋獲禽。宣王飲酒，以告嘉功。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>乾為日、為吉，伏坤為車、為田，艮為禽獲。乾為王、乾又為大明，故曰宣王。兌為飲、為告。乾為功。吉日、車攻，皆《小雅》美宣王詩篇名，禽、攻為韻，與《易》《比九五》象辭禽中韻正合。［尾按：此註出入特大］</p><h3 id="履之姤" tabindex="-1">履之姤 <a class="header-anchor" href="#履之姤" aria-label="Permalink to “履之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>金帛貴寶，宜與我市。嫁取有息，利得過母。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>乾為金、為貴、為寶，伏坤為帛、為我，巽為市。震為嫁、為生、為息。巽為母。○金帛貴、與，依汲古，宋元本作重伯黃、作以。息，汲古作恩，依元本。利得，依宋元本，汲古作得利。母，依宋元，汲古作倍。</p><h3 id="履之萃" tabindex="-1">履之萃 <a class="header-anchor" href="#履之萃" aria-label="Permalink to “履之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>延頸望酒，不入我口。深以自喜，利得無有。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>詳《訟》之《益》。</p><h3 id="履之升" tabindex="-1">履之升 <a class="header-anchor" href="#履之升" aria-label="Permalink to “履之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>牧為代守，饗食甘賜。得吏士意，戰大破胡，長安國家。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>此用李牧事。坤為養、為牧、為邑、為北，故曰代。伏艮為守，兌為饗。坤為甘，震為吏士、為戰，兌為折，坤為胡，故曰破胡。坤為安、為國家。巽為長。○食、吏，從宋元本，汲古作養、作利，非。家音姑。○《史記》&quot;李牧為代守，日饗士不與匈奴戰，後大破胡&quot;。</p><h3 id="履之困" tabindex="-1">履之困 <a class="header-anchor" href="#履之困" aria-label="Permalink to “履之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>日出溫谷，臨照萬國。高明淑仁，虞夏配德。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>離為日、為溫，兌為谷，故曰日出溫谷。伏艮為國，震為萬、為臨，離日為照，故曰照臨萬國。艮為高、為明，震為淑仁、為帝王，故曰虞夏。○仁，汲古作人，德作合，依宋元。</p><h3 id="履之井" tabindex="-1">履之井 <a class="header-anchor" href="#履之井" aria-label="Permalink to “履之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>逐兔索烏，破我弓車。日暮不及，失利後時。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>通《噬嗑》。震為兔、為逐，艮為求、為烏，故曰逐兔索烏。坎為破、為弓、為車，離日，坎暮，坎蹇，故不及。巽為利，震為後、為時，坎為失，故曰失利後時。</p><h3 id="履之革" tabindex="-1">履之革 <a class="header-anchor" href="#履之革" aria-label="Permalink to “履之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>訛言妄語，傳相詿誤。道左失跡，不知所處。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>二上正反兩兌口相背，故曰訛言妄語、曰傳相詿誤。《戰國韓策》&quot;詿誤人主&quot;，《漢書》&quot;景帝紀詿誤吏民&quot;，言疑誤也。艮為道，震為左、為跡，伏坎為失。○所，依宋本，汲古作戶。○此可解《困彖》&quot;有言不信&quot;。</p><h3 id="履之鼎" tabindex="-1">履之鼎 <a class="header-anchor" href="#履之鼎" aria-label="Permalink to “履之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>履虎躡蛇，貶損我威。君子失車，去其國家。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>此用伏象《屯》。震為履躡，艮為虎，坤為蛇，坤柔故損威。震為威也。艮為君子，坤為車、為喪，故失車。坤為家國，震為去。○蛇、車，依宋本，汲古作尾、作否。</p><h3 id="履之震" tabindex="-1">履之震 <a class="header-anchor" href="#履之震" aria-label="Permalink to “履之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>本根不固，華葉落去。更為孤嫗，不得相視。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>通《巽》。下斷，故曰本根不固，華葉落去。兌為華，巽隕落。嫗，老母也。巽為母、為寡，故曰孤嫗。離目為視。○視，依汲古，宋元本作親。○兌為華可解《大過九五》&quot;巽隕落&quot;，見《左傳》。</p><h3 id="履之艮" tabindex="-1">履之艮 <a class="header-anchor" href="#履之艮" aria-label="Permalink to “履之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>五軛四軏，優得饒有。陳力就列，騶虞喜悅。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《小畜》。惟彼作四軏，此作軏，音月。《說文》&quot;轅端持衡者&quot;，皆取艮象。騶虞亦艮象，白虎黑文。○軏，汲古訛國，喜悅作悅喜，均依宋元本。</p><h3 id="履之漸" tabindex="-1">履之漸 <a class="header-anchor" href="#履之漸" aria-label="Permalink to “履之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>黃帝紫雲，聖哲且神。光明見祥，告我無殃。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>通《歸妹》。震為帝、為黃，坎為雲，九宮九色，紫離九，故曰紫雲。坎為聖哲，震為神、為福祥，坎為殃。震解，故無殃，震為言，故曰告。○光明見祥，從汲古，宋元本作光見福祥。○《左傳》：&quot;黃帝有雲瑞，故以雲紀官&quot;。</p><h3 id="履之歸妹" tabindex="-1">履之歸妹 <a class="header-anchor" href="#履之歸妹" aria-label="Permalink to “履之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>五利四福，俱田高邑。黍稷盛茂，多獲槁稻。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>通《漸》。巽卦數五，為利，故曰五利。震為福，卦數四，故曰四福。巽為高，艮為邑，震為黍稷、為盛茂、為稻，離枯，故曰槁稻。○田，依汲古，宋本作佃。佃，治田也。《詩無田甫田》義同佃。○此巽五震四卦數之證。</p><h3 id="履之豐" tabindex="-1">履之豐 <a class="header-anchor" href="#履之豐" aria-label="Permalink to “履之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>群虎入邑，求索肉食。大人衛守，君不失國。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>通《渙》。艮為虎，正反艮，故曰群虎。巽入艮邑，艮求。坎為肉、為食，五為大人，艮為守，故曰大人衛守。震為君，艮為國，坎失，震為主，故不失國。○此坎為肉之證，可解《噬嗑》。</p><h3 id="履之旅" tabindex="-1">履之旅 <a class="header-anchor" href="#履之旅" aria-label="Permalink to “履之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>烏子鵲雛，常與母居。願慕群侶，不離其巢。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>離為烏鵲，伏震為子，兌為雛，巽為母，艮為居，伏坎為心、為願慕，離為巢，艮止，故不離。○離，依宋元，汲古作育，非。</p><h3 id="履之巽" tabindex="-1">履之巽 <a class="header-anchor" href="#履之巽" aria-label="Permalink to “履之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>蹇驢不材，駿驥失時。筋勞力盡，疲於沙邱。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>通《震》。為馬，坎蹇，故曰蹇驢。震為材，坎折，故不材。震為駿驥，艮為時，坎陷故失時，坎為勞疲。艮為沙、為邱。丁宴雲：《列子說符篇》：&quot;穆公九方皋求馬，三月而反，曰得之矣，在沙邱&quot;。按：坎為脊、為要，筋力或為坎象。</p><h3 id="履之兌" tabindex="-1">履之兌 <a class="header-anchor" href="#履之兌" aria-label="Permalink to “履之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>玄鬣黑顙，東歸高鄉。朱鳥道引，靈龜載莊。遂抵天門，見我貞君。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>通《艮》。坎為玄，震為鬣，艮為顙，坎為黑，故曰玄鬛黑顙。互震為東、為歸。艮為高鄉、為鳥。坎赤，故曰朱鳥。艮為龜，居西北，故曰天門。震為君，艮為貞，故曰貞君。載莊，言載運行李也。</p><h3 id="履之渙" tabindex="-1">履之渙 <a class="header-anchor" href="#履之渙" aria-label="Permalink to “履之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>探巢得雛，鳩鵲來俱，使我音娛。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>艮為巢、為探，伏兌為雛。離為鳩，震為鵲，故曰鳩鵲來俱。震為音、為娛。○音，依宋元本，汲古作欣。</p><h3 id="履之節" tabindex="-1">履之節 <a class="header-anchor" href="#履之節" aria-label="Permalink to “履之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>安上宜官，一日九遷。升擢超等，牧養常山，君臣得安。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>互艮為官、為安，陽在上，故曰安上。伏離為日，坎數一，故曰一日。震為遷、為升，數九，故曰九遷。艮為山、為臣。震為君。○汲古無末句，宋元本有，有，文氣始足。</p><h3 id="履之中孚" tabindex="-1">履之中孚 <a class="header-anchor" href="#履之中孚" aria-label="Permalink to “履之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>大頭明目，載受嘉福。三雀飛來，與祿相得。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>伏大坎，故曰大頭，互大離，故曰明目。震為載、為嘉福、為雀，數三，又為飛、為祿，故曰三雀飛來，與祿相得。</p><h3 id="履之小過" tabindex="-1">履之小過 <a class="header-anchor" href="#履之小過" aria-label="Permalink to “履之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>遠視千里，不見黑子。離婁之明，無益於光。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>震為遠、為千里，艮為視，互大坎隱伏，故不見。黑子，坎為黑，震為子也。伏大離，故曰離婁之明。艮為光，居坎下，故無益於光。○三四句依宋元本，汲古作&quot;離婁明視，移於小人&quot;，失韻。移，益字之訛，小人乃光形之訛。而汲古等本不知其訛，反註雲一作云云，疏已。又於光，汲古註作為光，亦非。</p><h3 id="履之既濟" tabindex="-1">履之既濟 <a class="header-anchor" href="#履之既濟" aria-label="Permalink to “履之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>三女為姦，俱遊高園。背夫夜行，與伯笑言。不忍主母，為失醴酒，冤尤誰告。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>此用《履》伏象。謙坤為女，震數三，故曰三女。坤為姦，故曰三女為姦。艮為園，巽為高，故曰高園。坎為夫、為夜，艮為背，震行，故曰背夫夜行。震為伯、為笑言，正反震，故曰與伯笑言。坤母震主，故曰主母。坎為憂，故曰不忍。坎為酒、為失、為冤尤，坎隱伏，故無可告語。○為，從宋元本，汲古作成。俱遊高園，依宋元本補，汲古等本俱無。主母，依宋元本，汲古作王母。為失醴酒，冤尤誰告。依汲古，宋元作&quot;失禮酒冤，皇天誰告&quot;，非，事詳後《離》之《訟》。</p><h3 id="履之未濟" tabindex="-1">履之未濟 <a class="header-anchor" href="#履之未濟" aria-label="Permalink to “履之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>日辰不良，強弱相振。一鳥兩雛，客勝主人。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>此仍用《履》伏象。○一鳥兩雛，依汲古，宋元本作一雌，未知孰是。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
